(async()=>{
let payload=window.RADAR_DATA, loadFailed=false;
if(location.protocol.startsWith('http')){try{const r=await fetch('data/bundle.json',{cache:'no-store'});if(!r.ok)throw Error('HTTP');const data=await r.json();if(!Array.isArray(data.jobs)||!Array.isArray(data.platforms)||!data.update)throw Error('Schema');payload=data}catch{loadFailed=true}}
const {jobs,platforms,excluded,projects=[],update={},config={}}=payload;
const date=v=>v?new Intl.DateTimeFormat('ru-RU',{timeZone:'Asia/Tbilisi',dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'Ещё не выполнялось';
const effectiveStatus=j=>j.status==='verified'&&(!j.last_verified_at||Date.now()-Date.parse(j.last_verified_at)>(config.verification_ttl_hours||48)*3600000)?'needs_review':j.status;
const statusNames={verified:'Подтверждена',needs_review:'Требует проверки',closed:'Закрыта',archived:'В архиве'};
const jobStatus=j=>badge(statusNames[effectiveStatus(j)]||'Требует проверки',effectiveStatus(j)==='verified'?'':'review');
const isNew=j=>!!j.first_seen_at&&Date.now()-Date.parse(j.first_seen_at)>=0&&Date.now()-Date.parse(j.first_seen_at)<86400000;

const $=s=>document.querySelector(s),esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let fav=read('jrg-favorites',[]);if(!Array.isArray(fav))fav=[];let progress=read('jrg-progress',{});let state={page:'overview',query:'',sort:'priority',filters:{}};
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('Браузер не разрешает сохранение. Изменения доступны до закрытия страницы.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
if(read('jrg-dark',false))document.body.classList.add('dark');$('#theme').onclick=()=>{document.body.classList.toggle('dark');save('jrg-dark',document.body.classList.contains('dark'))};
const fmt={Remote:'Удалённо',Office:'Офис',Hybrid:'Гибрид',Unknown:'Формат уточнить'};
const badge=(s,cls='')=>`<span class="badge ${cls}">${esc(s)}</span>`;
const star=j=>`<button class="fav" data-fav="${j.id}" aria-label="${fav.includes(j.id)?'Убрать из избранного':'В избранное'}: ${esc(j.company)}" aria-pressed="${fav.includes(j.id)}">${fav.includes(j.id)?'★':'☆'}</button>`;
const link=(j,label='Открыть вакансию')=>`<a class="apply" href="${esc(j.current_url||j.url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const tags=j=>`<div class="tags">${isNew(j)?badge('Новое'):''}${badge('Приоритет '+j.priority)}${badge(fmt[j.work_format],'neutral')}${badge(j.employment_type,'neutral')}</div>`;
function overview(){
const active=jobs.filter(j=>effectiveStatus(j)==='verified'&&j.kind!=='talent_pool');const reviews=jobs.filter(j=>effectiveStatus(j)==='needs_review');const news=jobs.filter(isNew);const counts=Object.fromEntries(Object.keys(fmt).map(k=>[k,jobs.filter(j=>j.work_format===k).length]));
const stale=!update.last_database_update||Date.now()-Date.parse(update.last_database_update)>(config.stale_run_hours||36)*3600000;
$('.notice').innerHTML=`<span>ⓘ</span><div><strong>${loadFailed?'Не удалось получить свежую базу':stale?'База давно не обновлялась':update.last_run_outcome==='failed'?'Последний запуск завершился ошибкой':'Автоматическая проверка: ограниченное покрытие'}</strong><br>${loadFailed?'Показан встроенный снимок. Попробуйте обновить страницу.':esc(update.coverage_note||'Автоматизация ещё не запускалась.')} Подтверждение вакансии не гарантирует соответствие требованиям и возможность выплат.</div>`;
$('#overview').innerHTML=`<div class="stats"><div class="stat"><span>Подтверждённые вакансии</span><b class="value accent">${active.length}</b><small>Подтверждение не старше ${config.verification_ttl_hours||48} ч</small></div><div class="stat"><span>Новые за 24 часа</span><b class="value">${news.length}</b><small>По дате обнаружения системой</small></div><div class="stat"><span>Требуют проверки</span><b class="value">${reviews.length}</b><small>Ошибки и неподтверждённые записи</small></div><div class="stat"><span>Платформы в каталоге</span><b class="value">${platforms.length}</b><small>Доступность выплат не подтверждена</small></div></div><div class="twocol"><div class="panel"><div class="panelhead"><div><h2>Возможности по формату</h2><p style="font-size:13px">${jobs.length} записей, включая требующие проверки</p></div><button data-page="jobs">Все вакансии</button></div><div class="bars">${Object.keys(fmt).map(k=>`<div><div class="barlabel"><span>${fmt[k]}</span><strong>${counts[k]}</strong></div><div class="track"><i style="width:${counts[k]/Math.max(jobs.length,1)*100}%"></i></div></div>`).join('')}</div></div><div class="panel"><h2>Состояние радара</h2><div class="rowmini"><span>Последний результат</span><strong>${esc({success:'Проверка выполнена',partial:'Частичная проверка',failed:'Ошибка',running:'Выполняется'}[update.last_run_outcome]||'Не запускался')}</strong></div><div class="rowmini"><span>Последняя попытка</span><strong>${date(update.last_run_at)}</strong></div><div class="rowmini"><span>Последнее сохранение базы</span><strong>${date(update.last_database_update)}</strong></div><div class="rowmini"><span>Ручная дата исходной таблицы</span><strong>21.11.2026</strong></div><div class="rowmini"><span>Расписание</span><strong>≈ 10:00 · Тбилиси</strong></div><div class="rowmini"><span>Плановый запуск подтверждён</span><strong>${update.scheduled_run_confirmed?'Да':'Пока нет'}</strong></div></div></div><div class="quick"><button data-quick="Remote"><strong>Работа из дома</strong><small>Удалённый формат</small></button><button data-page="platforms"><strong>Попробовать новое</strong><small>AI, краудтестинг и гибкие проекты</small></button><button data-page="favorites"><strong>Ваш короткий список</strong><small>Сохранённые варианты</small></button></div><details class="panel" style="margin-top:20px"><summary>Последние результаты источников</summary>${(update.source_results||[]).map(r=>`<div class="rowmini"><strong>${esc(r.source_id)}</strong><span>${esc(r.status==='ok'?'Получен список: '+r.returned+' записей':r.error||r.status)}</span></div>`).join('')||'Запусков ещё не было'}</details><p class="localnote">Избранное и прогресс сохраняются только в этом браузере. Статус подтверждения автоматически устаревает через ${config.verification_ttl_hours||48} часов.</p>`;
}
const filterdefs={category:['Направление',['Customer Support','QA','AI','Другие направления']],work_format:['Формат',Object.keys(fmt)],employment_type:['Занятость',['Full-time','Part-time','Freelance','Contract','Task-based','Уточнить']],languages:['Язык',['RU','EN','GE']],priority:['Приоритет',['A','B','C']],status:['Актуальность',['needs_review','verified','closed','archived']]};
const filterlabels={...fmt,needs_review:'Требует проверки',verified:'Подтверждена',closed:'Закрыта',archived:'В архиве'};
function buildFilters(){let defs=state.page==='platforms'?{category:['Направление',[...new Set(platforms.map(p=>p.category))]],progress:['Мой прогресс',['Не начато','Регистрация','KYC','Прохождение тестов','Ожидание проекта','Начало работы','Отказ']]}:filterdefs;$('#filters').innerHTML=Object.entries(defs).map(([k,[label,values]])=>`<label>${label}<select data-filter="${k}"><option value="">Все</option>${values.map(v=>`<option value="${esc(v)}">${esc(filterlabels[v]||v)}</option>`).join('')}</select></label>`).join('');for(const s of document.querySelectorAll('[data-filter]')){s.value=state.filters[s.dataset.filter]||'';s.onchange=()=>{state.filters[s.dataset.filter]=s.value;renderResults()}}}
function navigate(page){state.page=['overview','jobs','platforms','favorites'].includes(page)?page:'overview';state.query='';state.filters={};$('#search').value='';$('#overview').hidden=state.page!=='overview';$('#listing').hidden=state.page==='overview';let texts={overview:['Ваш следующий шаг','Вакансии и возможности заработка — в одном месте.','ОБЗОР'],jobs:['Вакансии','Подходящие направления. Все условия и оговорки под рукой.','ВАКАНСИИ'],platforms:['Платформы заработка','Исследуйте возможности и отслеживайте свой прогресс.','ПЛАТФОРМЫ'],favorites:['Избранное','Ваш личный список возможностей, к которым стоит вернуться.','ИЗБРАННОЕ']}[state.page];$('#title').textContent=texts[0];$('#subtitle').textContent=texts[1];$('#crumb').textContent=texts[2];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));$('#favcount').textContent=fav.length;buildFilters();overview();renderResults()}
function renderResults(){let isP=state.page==='platforms';let list=(isP?platforms:jobs).filter(j=>(state.page!=='favorites'||fav.includes(j.id))&&JSON.stringify(j).toLowerCase().includes(state.query.toLowerCase())&&Object.entries(state.filters).every(([k,v])=>!v||(k==='progress'?(progress[j.id]||'Не начато')===v:k==='languages'?j.languages.includes(v):(k==='status'?effectiveStatus(j):j[k])===v)));list.sort((a,b)=>state.sort==='priority'?(a.priority||'').localeCompare(b.priority||''):(state.sort==='company'?(a.company||a.name):(a.title||a.category)).localeCompare(state.sort==='company'?(b.company||b.name):(b.title||b.category),'ru'));$('#filterCount').textContent=Object.values(state.filters).filter(Boolean).length||'';$('#resultCount').textContent=`${isP?'Платформы':'Вакансии'}: ${list.length} из ${isP?platforms.length:jobs.length}`;
if(isP){$('#results').innerHTML=`<div class="platformgrid">${list.map(p=>`<article class="platform"><div class="top"><h3>${esc(p.name)}</h3>${badge('Проверить','review')}</div><p>${esc(p.category)}</p><p class="work">${esc(p.work)}</p><div class="rowmini"><span>Порог входа</span><strong>${esc(p.entry)}</strong></div><div class="rowmini"><span>Оплачиваемые проекты</span><strong>${esc(p.projects_status)}</strong></div><div class="actions">${link(p,'Открыть сайт')}<button data-detail="${p.id}">Условия</button></div><label>Мой прогресс<select data-progress="${p.id}">${['Не начато','Регистрация','KYC','Прохождение тестов','Ожидание проекта','Начало работы','Отказ'].map(v=>`<option ${progress[p.id]===v?'selected':''}>${v}</option>`).join('')}</select></label></article>`).join('')}</div><div class="panel" style="margin-top:20px"><h2>Базы кандидатов · ${projects.filter(p=>p.kind==='talent_pool').length}</h2><p>Это регистрация интереса, не подтверждённая оплачиваемая работа.</p>${projects.map(p=>`<div class="rowmini"><div><strong>${esc(p.title)}</strong><br><small>${p.status==='talent_pool'?'Приглашение в базу кандидатов':'Требует проверки'} · ${date(p.last_verified_at)}</small></div><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Открыть</a></div>`).join('')}</div><p class="localnote">Доступность платформы не означает наличие оплачиваемого проекта. Выплаты и ставки из Excel требуют проверки. Личный прогресс хранится только в этом браузере.</p><details class="panel"><summary>Исключённые платформы · 6</summary><p>Исходные причины сохранены, но не проверены заново. Автоматическое возвращение в рекомендации запрещено.</p>${excluded.map(p=>`<div class="rowmini"><strong>${esc(p.name)}</strong><span>${esc(p.reason)}</span></div>`).join('')}</details>`}
else $('#results').innerHTML=list.length?`<div class="tablewrap"><table><thead><tr><th>Вакансия / компания</th><th>Условия</th><th>Актуальность</th><th>Действия</th></tr></thead><tbody>${list.map(j=>`<tr><td><button class="jobtitle" data-detail="${j.id}">${esc(j.title)}</button><div class="company">${esc(j.company)}</div>${tags(j)}</td><td>${esc(j.salary)}<div class="company">${esc(j.languages)}</div></td><td>${jobStatus(j)}<div class="company">${j.last_checked_at?date(j.last_checked_at):'Автопроверки не было'}</div></td><td>${star(j)}<div class="jobactions">${link(j,'Отклик')}</div></td></tr>`).join('')}</tbody></table></div><div class="cards">${list.map(j=>`<article class="jobcard"><div class="top"><div><h3>${esc(j.title)}</h3><div class="company">${esc(j.company)}</div></div>${star(j)}</div>${tags(j)}<div class="salary">${esc(j.salary)}</div>${jobStatus(j)}<p style="font-size:12px">Последняя проверка: ${date(j.last_checked_at)}<br>Подтверждение: ${date(j.last_verified_at)}</p><div class="jobactions">${link(j,'Отклик')}<button data-detail="${j.id}">Подробнее</button></div></article>`).join('')}</div>`:'<div class="empty"><h2>Здесь пока пусто</h2><p>Измените фильтры или добавьте вакансии в избранное.</p></div>';
if(isP&&!list.length)$('#results').insertAdjacentHTML('afterbegin','<div class="empty">Платформ по этим условиям не найдено.</div>')}
function detail(id){let j=[...jobs,...platforms].find(j=>j.id===id);if(!j)return;let isJob=!!j.company;let fields=isJob?{'Компания':j.company,'Направление':j.category,'Формат':fmt[j.work_format],'Занятость':j.employment_type,'География':j.geography,'Доступность для гражданина Грузии':'Требует проверки; география не подтверждает выплаты','Языки':j.languages,'Опыт':j.experience,'График и условия':j.schedule,'Оплата':j.salary,'Исходный статус на 21.11.2026':j.source_status,'Оговорки':j.notes,'Источник':j.source,'Лист Excel':j.source_sheet,'Ручная дата исходной проверки':j.source_manual_checked_on||'Не было','Обнаружено системой':j.first_seen_at?date(j.first_seen_at):'Исходный импорт; дата не установлена','Дата публикации':j.published_at?date(j.published_at):'Неизвестна','Последняя попытка проверки':date(j.last_checked_at),'Последнее подтверждение автоматикой':date(j.last_verified_at),'Последний результат':j.last_check_result?.evidence||'Проверок ещё не было','Текущее описание источника':j.current_source?.description||j.description||'Нет новых сведений','Соответствие профилю':j.match_notes||'Требует оценки'}:{'Направление':j.category,'Что делать':j.work,'Порог входа':j.entry,'Доступность для Грузии':'Требует проверки по официальному источнику','Выплаты — исходные сведения, не подтверждены':j.payout,'Тесты — исходные сведения':j.tests,'KYC':j.kyc,'Оплачиваемые проекты':j.projects_status,'Подтверждённые ставки':'Отсутствуют','Исходные заметки (включая неподтверждённые ставки)':j.notes,'Исходный статус регистрации':j.source_registration,'Последняя проверка':date(j.last_checked_at)};$('#detailBody').innerHTML=`<h2>${esc(j.title||j.name)}</h2>${isJob?tags(j):''}<dl>${Object.entries(fields).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><p><a href="${esc(j.current_url||j.url)}" target="_blank" rel="noopener noreferrer">${esc(j.url)}</a></p>${link(j,isJob?'Открыть источник':'Открыть сайт платформы')}`;$('#detail').showModal()}
document.addEventListener('click',e=>{let b=e.target.closest('[data-page],[data-fav],[data-detail],[data-quick]');if(!b)return;if(b.dataset.page){location.hash=b.dataset.page;if(state.page===b.dataset.page)navigate(b.dataset.page)}if(b.dataset.fav){let id=b.dataset.fav;fav=fav.includes(id)?fav.filter(x=>x!==id):[...fav,id];save('jrg-favorites',fav);$('#favcount').textContent=fav.length;renderResults()}if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.quick){location.hash='jobs';navigate('jobs');state.filters.work_format=b.dataset.quick;buildFilters();renderResults()}});
document.addEventListener('change',e=>{if(e.target.dataset.progress){progress[e.target.dataset.progress]=e.target.value;save('jrg-progress',progress);toast('Прогресс сохранён в этом браузере');if(state.filters.progress)renderResults()}});
$('#close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail')&&e.offsetX<0)$('#detail').close()};$('#search').oninput=e=>{state.query=e.target.value;renderResults()};$('#sort').onchange=e=>{state.sort=e.target.value;renderResults()};$('#filterToggle').onclick=()=>{let el=$('#filters');el.hidden=!el.hidden;$('#filterToggle').setAttribute('aria-expanded',!el.hidden)};$('#reset').onclick=()=>{state.filters={};state.query='';$('#search').value='';buildFilters();renderResults()};window.addEventListener('hashchange',()=>{if(state.page!==location.hash.slice(1))navigate(location.hash.slice(1))});$('#jobsnavcount').textContent=jobs.length;navigate(location.hash.slice(1)||'overview');

})();
